def sync_announcement_status(apps, schema_editor):
    """Legacy rows: ``is_published=True`` becomes the authoritative status."""
    Announcement = apps.get_model('learning', 'Announcement')
    now = timezone.now()
    for announcement in Announcement.objects.filter(is_published=True, status='draft'):
        announcement.status = 'published'
        if announcement.published_at is None:
            announcement.published_at = announcement.scheduled_at or now
        announcement.save(update_fields=['status', 'published_at'])


def seed_default_form_fields(apps, schema_editor):
    """Give every existing competition the standard registration questions.

    Uses only historical models (real model instances cannot be queried
    against migration state), mirroring
    ``learning.models.seed_default_registration_fields``.
    """
    Competition = apps.get_model('learning', 'Competition')
    RegistrationFormField = apps.get_model('learning', 'RegistrationFormField')
    if RegistrationFormField.objects.exists():
        return
    field_defaults = {
        'education_level': ['Class 9-10', 'Class 11-12', 'Diploma / Associate', 'Bachelor', 'Master or higher', 'Self-taught'],
        'programming_experience': ['Complete beginner', 'Some basics', 'Intermediate', 'Advanced'],
        'participation_type': ['Individual', 'Team'],
    }
    for competition in Competition.objects.all():
        for order, (label, key, ftype, required) in enumerate(FORM_FIELD_SEED, 1):
            RegistrationFormField.objects.create(
                competition=competition,
                label=label,
                field_key=key,
                field_type=ftype,
                required=required,
                options=field_defaults.get(key, []),
                order=order,
                is_default=True,
            )


